/* Scoped to this route by the compiler, so `.tally` here cannot reach a
   `.tally` anywhere else on the site. */
.tally {
  padding: 1rem;
  border: 1px solid var(--w-border);
  border-radius: 12px;
}

.runtime {
  font-size: .875rem;
  opacity: .7;
}

export default class {
  count = 6
  runtime = 'JavaScript, everywhere'

  doubled() {
    return this.count * 2
  }
}

export default class {
  count: number = 6
  runtime: string = 'TypeScript, everywhere'

  doubled(): number {
    return this.count * 2
  }
}

pub struct Companion {
    pub count: i32,
    pub runtime: &'static str,
}

impl Companion {
    pub fn new() -> Self {
        Self { count: 6, runtime: "Rust, linked into the app" }
    }

    pub fn doubled(&self) -> i32 {
        self.count * 2
    }
}

