import { OrderService } from '../../services/orders.js'

@Controller
export class OrdersController {
  // A route is thin on purpose: one request in, one call down, one response.
  static GET() {
    return { orders: new OrderService().list() }
  }
}

import { OrderRepository } from '../repositories/orders.js'

@Service
export class OrderService {
  // Injected rather than constructed inline, so a test supplies its own
  // repository without reaching for a module mock.
  constructor(repository = new OrderRepository()) {
    this.repository = repository
  }

  list() {
    return this.repository.all()
  }
}

@Repository
export class OrderRepository {
  // Owns storage and nothing else. A repository, a client and a delegate are
  // peers: none of them calls another.
  all() {
    return [{ sku: 'anvil', level: 4 }]
  }
}

@Controller
export class OrdersController {
  // The same shape as a yon.js: a class, static methods named for the HTTP
  // method, and a return value that becomes the response.
  static GET(request: YonRequest): { orders: Order[] } {
    return { orders: OrderService.list() }
  }
}

