import java.util.Map;

@Controller
class OrdersController {
    // No main: Tachyon appends the protocol and finds this class by the
    // annotation on it rather than by its name. A method not declared here
    // answers 405 without being written.
    static YonResponse GET(YonRequest request) {
        return YonResponse.json(Json.write(Map.of("id", request.parameter("id"))));
    }
}

@Service
public class OrderService {
    // Declared and checked today; not yet reachable from a handler, because a
    // compiled handler is one source file and this is another.
    static java.util.List<String> list() {
        return java.util.List.of("anvil");
    }
}

@Repository
public class OrderRepository {
  static java.util.List<String> all() {
