[Controller]
class OrdersController
{
    // Only the methods this route answers. Every other one is a 405 without
    // being written, and nothing here reads stdin or writes an envelope: the
    // protocol runtime is compiled beside this file.
    //
    // Json is in scope without naming a namespace, under the same name every
    // other language here gives it.
    static YonResponse GET(YonRequest request) =>
        YonResponse.Json(Json.Write(new { orders = OrderService.List() }));

    static YonResponse POST(YonRequest request) =>
        YonResponse
            .Json(Json.Write(new { created = request.Parsed()["name"]?.ToString() }))
            .Status(201);
}

