#[Controller]
struct OrdersController;

impl OrdersController {
    // Only the methods this route answers. Every other one is a 405 without
    // being written: the appended runtime supplies a default for each.
    //
    // Json is in scope without an import. Rust has none in its standard
    // library and this compiles with no Cargo, so Tachyon supplies one rather
    // than leaving a handler to escape a string by hand.
    fn GET(request: &YonRequest) -> YonResponse {
        YonResponse::json(Json::map([("id", request.parameter("id"))]))
    }

    fn POST(request: &YonRequest) -> YonResponse {
        YonResponse::json(Json::map([("echoed", request.json())])).status(201)
    }
}

